import{_ as o,l as s,o as e,c as n,v as t,p as l,x as r,d,i as p,S as P}from"./chunks/framework.InCnrqk-.js";const N=JSON.parse('{"title":"IPv6 地址与 NDP","description":"","frontmatter":{"title":"IPv6 地址与 NDP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ipv6-ndp.md","filePath":"cs/ipv6-ndp.md","lastUpdated":1789023840000}'),c={name:"cs/ipv6-ndp.md"};function E(A,a,h,B,_,v){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="ipv6-地址与-ndp" tabindex="-1">IPv6 地址与 NDP <a class="header-anchor" href="#ipv6-地址与-ndp" aria-label="Permalink to &quot;IPv6 地址与 NDP&quot;">​</a></h1><div class="epigraph"><p>128 位地址仍用前缀划定链路；链路上的解析改成邻居发现，不再广播 ARP。</p><footer>—— 据 Deering and Hinden, RFC 8200；Narten 等对邻居发现的整理</footer></div><p><a href="/cs/ipv6-contrast">上一课</a>对照了头格式：无中间分片、无头校验、地址变长。本课不重列扩展头。缺口是地址怎么用、链路上怎么找到邻机：前缀仍决定直连，解析协议换成 NDP（邻居请求/通告），路由器通告代替很多 DHCP 选项。本课不把距离向量提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/ipv6-contrast">IPv6 对照</a>说邻居发现取代 ARP，但没写表怎么填。主机仍要判断目的是否在链路上（前缀长），再把下一跳 IPv6 地址译成 MAC。NDP 用 ICMPv6 消息、组播而不是以太网广播问遍全网。无状态地址自动配置（SLAAC）让主机用通告的前缀自生成接口标识。缺口是<strong>IPv6 的一跳合同</strong>，与 <a href="/cs/arp-cache">ARP 缓存</a> 同层、不同报文。</p><p><span class="marginnote">链路本地地址 <code>fe80::/10</code> 只在一跳有效。全局前缀由路由器通告。重复地址检测在启用前先邻居请求自己。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查邻居缓存；未命中则向被请求节点组播发邻居请求，对端单播通告。路由器通告携带前缀、MTU、是否当默认路由。重定向告诉「更好的下一跳」。缓存同样有可达性探测与超时，避免把流量打到已离开的 MAC。</p>',8)),(e(),l(P,null,{default:r(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DST%5B%22%E4%B8%8B%E4%B8%80%E8%B7%B3%20IPv6%22%5D%20--%3E%20NC%5B%22%E9%82%BB%E5%B1%85%E7%BC%93%E5%AD%98%22%5D%0A%20%20NC%20--%3E%20NS%5B%22%E7%BB%84%E6%92%AD%E9%82%BB%E5%B1%85%E8%AF%B7%E6%B1%82%22%5D%0A%20%20NS%20--%3E%20NA%5B%22%E9%82%BB%E5%B1%85%E9%80%9A%E5%91%8A%E5%A1%AB%E8%A1%A8%22%5D%0A%20%20RA%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%E9%80%9A%E5%91%8A%22%5D%20--%3E%20PFX%5B%22%E5%89%8D%E7%BC%80%E4%B8%8E%E9%BB%98%E8%AE%A4%E8%B7%AF%E7%94%B1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>NDP 把 ARP + 部分 ICMP 路由器发现收进 ICMPv6，仍只服务一跳。<a href="/cs/lpm">LPM</a> 在 IPv6 上同样按最长前缀。NAPT 不再是地址不足的理由；防火墙状态仍可存在。端到端：NDP 不保证全球到达，只保证这一跳封装对。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 SEND 与全部 RA 选项当必背，不引入 IPv4/IPv6 双栈过渡的全部隧道。路由如何填全球表，下一课距离向量。</p><p>后课默认：IPv6 链路上用 NDP 缓存邻接。控制平面如何学前缀，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RFC 8200 的地址仍靠前缀划链路；解析用 NDP。</li><li>路由器通告给出前缀与默认路由。</li><li>填全球转发表是下一课距离向量。</li><li>出处：RFC 8200；Kurose and Ross；邻居发现文献（Narten 等）。</li></ul>',7))])}const m=o(c,[["render",E]]);export{N as __pageData,m as default};
